n{width:48px;height:48px;border-radius:13px;background:rgba(85,150,255,.13);border:1px solid rgba(85,150,255,.24);display:grid;place-items:center;color:#79adff;font-size:18px}.eyebrow{color:#72a7e8;font-size:9px;letter-spacing:.12em;text-transform:uppercase;font-weight:800;margin-bottom:4px}.hero h1{font-size:23px;line-height:1.1;margin:0 0 6px}.meta,.note,.help{color:var(--muted);font-size:10px}.status{position:relative;z-index:1;display:inline-flex;align-items:center;gap:7px;padding:7px 11px;border:1px solid rgba(59,211,155,.18);border-radius:20px;background:rgba(59,211,155,.08);color:var(--green);font-size:10px;font-weight:800}.status:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px}.stat,.card{background:linear-gradient(145deg,rgba(13,34,53,.96),rgba(8,25,39,.96));border:1px solid var(--line);box-shadow:0 10px 28px rgba(0,0,0,.10)}.stat{padding:16px 17px;border-radius:12px;min-height:78px}.stat span{display:flex;align-items:center;gap:6px;color:var(--muted);font-size:8px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:8px}.stat strong{display:block;font-size:13px;line-height:1.35;word-break:break-word}.content{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(300px,.65fr);gap:16px}.card{overflow:hidden;border-radius:13px;margin-bottom:16px}.title{padding:14px 17px;border-bottom:1px solid var(--line);font-size:12px;font-weight:800;display:flex;align-items:center;justify-content:space-between}.body{padding:16px}.powers{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.btn{min-height:39px;width:100%;border:1px solid transparent;border-radius:8px;padding:10px 12px;background:linear-gradient(135deg,var(--blue),var(--blue2));box-shadow:0 6px 18px rgba(54,124,231,.13);color:#fff;font-size:11px;font-weight:800;cursor:pointer;transition:.15s}.btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.btn.secondary{background:#10283c;border-color:#244863;box-shadow:none}.btn.green{background:#137c5d}.btn.orange{background:#966114}.btn.red{background:#a63f4d}.credentials{display:grid;grid-template-columns:.7fr 1.3fr;gap:10px}.credential,.auto-user{background:rgba(5,19,31,.65);border:1px solid var(--line);border-radius:9px;padding:14px}.credential label,.auto-user label{display:block;color:var(--muted);font-size:8px;letter-spacing:.08em;text-transform:uppercase;margin-bottom:8px}.credential strong,.auto-user strong{font-size:13px}.password-row{display:flex;gap:6px;align-items:center}.password-row code{flex:1;word-break:break-all;color:#dce9f5}.mini{width:auto;min-height:30px;padding:6px 9px;font-size:9px}.empty-password{font-size:10px;color:var(--muted);line-height:1.55}.field{width:100%;padding:11px;border:1px solid var(--line2);background:#071a2a;color:#fff;border-radius:8px;margin:8px 0 12px;outline:none}.field:focus{border-color:var(--blue)}.danger{border-color:rgba(241,95,112,.24)}.danger .title{color:#ff9baa;background:rgba(241,95,112,.025)}.security-intro{display:flex;gap:11px;align-items:flex-start;margin-bottom:13px}.security-icon{width:34px;height:34px;flex:0 0 34px;border-radius:9px;display:grid;place-items:center;background:rgba(87,152,255,.1);color:#7cafef}.footer{text-align:center;color:#48657d;font-size:9px;padding-top:8px}.section-label{font-size:10px;color:#708aa0;text-transform:uppercase;letter-spacing:.1em;margin:1px 0 9px 2px;font-weight:800}@media(max-width:850px){.overview{grid-template-columns:1fr 1fr}.content{grid-template-columns:1fr}.powers{grid-template-columns:1fr 1fr}.hero{padding:21px}.wrap{margin-top:18px}}@media(max-width:560px){.top{height:62px}.topin,.wrap{padding-left:14px;padding-right:14px}.brand small{display:none}.back{font-size:10px}.hero{align-items:flex-start}.hero h1{font-size:18px}.server-icon{width:42px;height:42px}.overview{gap:8px}.stat{padding:13px;min-height:72px}.credentials{grid-template-columns:1fr}.password-row{flex-wrap:wrap}.password-row code{width:100%;flex-basis:100%;margin-bottom:4px}.powers{gap:7px}.body{padding:14px}}
</style></head><body><header class="top"><div class="topin"><a class="brand" href="/client"><span class="logo">N</span><span>Nodexa<small>HOSTING CLOUD</small></span></a><a class="back" href="/client#vps">← Tilbage til Client Area</a></div></header><main class="wrap">@if(session('success'))<div class="alert ok">{{session('success')}}</div>@endif @if($errors->any())<div class="alert err">{{$errors->first()}}</div>@endif @if($apiError)<div class="alert err">Flax API: {{$apiError}}</div>@endif @php($currentPassword=$storedPassword??($info['password']??$info['root_password']??$info['rootPassword']??$info['admin_password']??$info['adminPassword']??null)) @php($osDisplay=(string)($info['os_name']??$info['operatingSystem']??'')) @php($osCollection=collect($oses)) @php($selectedOs=$osCollection->first(function($os) use ($vps){return (string)($os['id']??$os['value']??$os['template_id']??'')===(string)$vps->os_id;})) @php($selectedOsName=is_array($selectedOs)?(string)($selectedOs['name']??$selectedOs['label']??$selectedOs['title']??''):'') @php($isWindows=stripos($osDisplay.' '.$selectedOsName,'windows')!==false) @php($currentUser=$isWindows?'Administrator':'root')<section class="hero"><div class="server-title"><div class="server-icon">◇</div><div><div class="eyebrow">Nodexa VPS Control</div><h1>{{$vps->hostname?:('VPS #'.$vps->id)}}</h1><div class="meta">VPS #{{$vps->id}} &nbsp;•&nbsp; Flax server #{{$vps->provider_server_id?:'—'}}</div></div></div><span class="status">{{str_replace('_',' ',$vps->status)}}</span></section><section class="overview"><div class="stat"><span>◉ IP-adresse</span><strong>{{$vps->ip_address?:($info['ip_address']??$info['ip']??'Afventer IP')}}</strong></div><div class="stat"><span>◆ Operativsystem</span><strong>{{$info['os_name']??$info['operatingSystem']??($selectedOsName?:('OS ID '.($vps->os_id?:'—')))}}</strong></div><div class="stat"><span>⌁ Hostname</span><strong>{{$vps->hostname?:($info['hostname']??'—')}}</strong></div><div class="stat"><span>● Status</span><strong>{{$info['status']??$vps->status}}</strong></div></section><div class="content"><div><div class="section-label">Serverkontrol</div><section class="card"><div class="title"><span>Strømstyring</span><span class="help">Flax power controls</span></div><div class="body powers">@foreach(['boot'=>['▶ Start','green'],'shutdown'=>['■ Luk ned','orange'],'restart'=>['↻ Genstart',''],'poweroff'=>['⚠ Tving sluk','red']] as $action=>$x)<form method="POST" action="/client/vps/{{$vps->id}}/power">@csrf<input type="hidden" name="action" value="{{$action}}"><button class="btn {{$x[1]}}">{{$x[0]}}</button></form>@endforeach</div></section><section class="card"><div class="title"><span>Serveradgang</span><span class="help">SSH / Remote Desktop</span></div><div class="body credentials"><div class="credential"><label>Administratorkonto</label><strong>{{$currentUser}}</strong><div class="note" style="margin-top:5px">{{$isWindows?'Remote Desktop':'SSH'}}</div></div><div class="credential"><label>Adgangskode</label>@if($currentPassword)<div class="password-row"><code id="vps-password" data-password="{{e($currentPassword)}}">••••••••••••</code><button type="button" class="btn mini secondary" onclick="togglePass(this)">Vis</button><button type="button" class="btn mini secondary" onclick="copyPass(this)">Kopiér</button></div>@else<div class="empty-password">Adgangskoden er ikke gemt i Nodexa endnu. Brug nulstilling én gang for at generere og gemme den krypteret.</div>@endif</div></div></section></div><aside><div class="section-label">Administration</div><section class="card"><div class="title"><span>Nulstil adgangskode</span><span class="help">Sikkerhed</span></div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/reset-password">@csrf<div class="security-intro"><div class="security-icon">⌾</div><div class="note">Nodexa vælger automatisk den korrekte administratorkonto ud fra operativsystemet.</div></div><div class="auto-user"><label>Konto der nulstilles</label><strong>{{$currentUser}}</strong><div class="note" style="margin-top:5px">{{$isWindows?'Windows · Administrator':'Linux · root'}}</div></div><button class="btn" style="margin-top:11px">Nulstil adgangskode</button></form></section><section class="card danger"><div class="title"><span>Geninstaller VPS</span><span class="help">Danger zone</span></div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/rebuild" onsubmit="return confirm('ADVARSEL: Alt data på VPS’en slettes permanent. Fortsæt?')">@csrf<div class="note"><strong style="color:#ff9baa">Advarsel:</strong> Geninstallation sletter alle filer og den gemte adgangskode permanent.</div><select class="field" name="os_id" required><option value="">Vælg operativsystem...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{$oid==$vps->os_id?'selected':''}}>{{$on}}</option>@endforeach</select><input type="hidden" name="confirm" value="REINSTALL"><button class="btn red">Geninstaller VPS</button></form></section></aside></div><div class="footer">Nodexa VPS Control &nbsp;•&nbsp; Server #{{$vps->id}} &nbsp;•&nbsp; Powered by Flax Hosting</div></main><script>function togglePass(b){var e=document.getElementById('vps-password'),s=e.dataset.shown==='1';e.textContent=s?'••••••••••••':e.dataset.password;e.dataset.shown=s?'0':'1';b.textContent=s?'Vis':'Skjul'}function copyPass(b){navigator.clipboard.writeText(document.getElementById('vps-password').dataset.password);var t=b.textContent;b.textContent='Kopieret ✓';setTimeout(function(){b.textContent=t},1200)}</script></body></html>